using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CurrentCompanions", menuName = "Data/Battle/Companions/Current Companions")]
public class CurrentCompanions : ScriptableObject
{
	[Header("Runtime Companions")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private List<RuntimeCompanion> runtimeCompanions = new List<RuntimeCompanion>();

	[Header("Companions List")]
	[SerializeField]
	private RecycleAction recycleAction;

	[Header("References")]
	[SerializeField]
	private GameObjectReference companionPanelGameObjectReference;

	[Header("Companion Reward")]
	[SerializeField]
	private CompanionReward companionReward;

	[Header("Save System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Debug")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool verbose;

	[SerializeField]
	private bool debugCompanions;

	[SerializeField]
	[ShowIf("debugCompanions")]
	private List<RuntimeCompanion> debugCompanionsList = new List<RuntimeCompanion>();

	[Header("Editor: Build State")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private List<CompanionData> buildCompanions;

	public List<GameObject> ActiveCompanions = new List<GameObject>();

	public List<GameObject> DecayedCompanions = new List<GameObject>();

	public List<RuntimeCompanion> RuntimeCompanions => runtimeCompanions;

	public void OnReset()
	{
		ActiveCompanions.Clear();
		DecayedCompanions.Clear();
	}

	public void OnResetToStartRunState()
	{
		runtimeCompanions.Clear();
		if (debugCompanions)
		{
			for (int i = 0; i < debugCompanionsList.Count; i++)
			{
				runtimeCompanions.Add(new RuntimeCompanion(debugCompanionsList[i]));
			}
		}
		else
		{
			LoadCompanions();
		}
		GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference();
	}

	private void LoadCompanions()
	{
		Character currentCharacter = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter;
		if (!saveSystem.HasModSentinelsSetBattleSaveKey(currentCharacter.CharacterName) || ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			LoadDefaultCompanions();
			return;
		}
		SaveSystem.ModSentinelsSetSave modSetInfo = saveSystem.LoadModSentinelsSetBattle(currentCharacter.CharacterName);
		CharacterCompanions.ModSentinelsSetsInfo modSentinelsSetsInfo = currentCharacter.CharacterCompanions.CustomCompanionsList.Find((CharacterCompanions.ModSentinelsSetsInfo _) => _.PublishedId == modSetInfo.PublishedId);
		if (modSentinelsSetsInfo == null)
		{
			LoadDefaultCompanions();
			return;
		}
		CharacterCompanions.SentinelSetInfo sentinelSetInfo = modSentinelsSetsInfo.SentinelSetInfosList.Find((CharacterCompanions.SentinelSetInfo _) => _.SetId == modSetInfo.SetId);
		if (sentinelSetInfo == null)
		{
			LoadDefaultCompanions();
			return;
		}
		for (int i = 0; i < sentinelSetInfo.Sentinels.Count; i++)
		{
			if (sentinelSetInfo.Sentinels[i] != null)
			{
				RuntimeCompanion runtimeCompanion = recycleAction.GetRuntimeCompanion(0, sentinelSetInfo.Sentinels[i]);
				runtimeCompanions.Add(runtimeCompanion);
			}
		}
		if (runtimeCompanions.Count < 2)
		{
			for (int j = runtimeCompanions.Count; j < ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingCompanionsAmount; j++)
			{
				RuntimeCompanion runtimeCompanion2 = recycleAction.GetRuntimeCompanion(0, RandomCompanionEnum.NO_UNKNOWN_DEVICE);
				runtimeCompanions.Add(runtimeCompanion2);
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.NewCompanionAcquired(runtimeCompanion2.CompanionData);
			}
		}
	}

	private void LoadDefaultCompanions()
	{
		for (int i = 0; i < ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.StartingCompanionsAmount; i++)
		{
			RuntimeCompanion runtimeCompanion = recycleAction.GetRuntimeCompanion(0, RandomCompanionEnum.NO_UNKNOWN_DEVICE);
			runtimeCompanions.Add(runtimeCompanion);
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.NewCompanionAcquired(runtimeCompanion.CompanionData);
		}
	}

	public void GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference()
	{
		companionReward.GetCompanionRewardLevelAndUpdateCompanionLevelRewardIntReference(higherLevelCompanion: false);
	}

	public void EndOfBattleInitialize()
	{
		if (ActiveCompanions.Contains(null))
		{
			Debug.Log("-------------CURRENT COMPANIONS END OF BATTLE INITIALIZE: Active Companions with null reference when it shouldnt----------------");
			ActiveCompanions.RemoveNullObjects();
		}
		if (DecayedCompanions.Contains(null))
		{
			Debug.Log("-------------CURRENT COMPANIONS END OF BATTLE INITIALIZE: Decayed Companions with null reference when it shouldnt----------------");
			DecayedCompanions.RemoveNullObjects();
		}
		List<GameObject> list = ActiveCompanions.Duplicate();
		int count = runtimeCompanions.Count;
		if (ActiveCompanions.Count + DecayedCompanions.Count < count)
		{
			Debug.Log("-------------CURRENT COMPANIONS END OF BATTLE INITIALIZE: Companion Amount not right, lost reference on Active or Decayed Companions List. Searching for references----------------");
			list.Clear();
			DecayedCompanions.Clear();
			ActiveCompanions.Clear();
			CompanionPanel component = companionPanelGameObjectReference.value.GetComponent<CompanionPanel>();
			GameObject gameObject = component.CompanionHolders.First().GetComponentInChildren<CompanionInitializer>(includeInactive: true).gameObject;
			if (gameObject.activeInHierarchy)
			{
				list.Add(gameObject);
			}
			else
			{
				DecayedCompanions.Add(gameObject);
			}
			if (runtimeCompanions.Count == 2)
			{
				GameObject gameObject2 = component.CompanionHolders[1].GetComponentInChildren<CompanionInitializer>(includeInactive: true).gameObject;
				if (gameObject2.activeInHierarchy)
				{
					list.Add(gameObject2);
				}
				else
				{
					DecayedCompanions.Add(gameObject2);
				}
			}
		}
		if (DecayedCompanions.Count > 0)
		{
			ActiveCompanions.Clear();
			for (int i = 0; i < count; i++)
			{
				ActiveCompanions.Add(null);
			}
			for (int j = 0; j < list.Count; j++)
			{
				CompanionInitializer componentInChildren = list[j].GetComponentInChildren<CompanionInitializer>();
				ActiveCompanions[componentInChildren.PositioningIndex] = list[j];
				componentInChildren.EndOfBattleInitialize();
			}
			for (int k = 0; k < DecayedCompanions.Count; k++)
			{
				CompanionInitializer componentInChildren2 = DecayedCompanions[k].GetComponentInChildren<CompanionInitializer>();
				ActiveCompanions[componentInChildren2.PositioningIndex] = DecayedCompanions[k];
				componentInChildren2.EndOfBattleInitialize();
			}
			DecayedCompanions.Clear();
		}
		else
		{
			ActiveCompanions = list.Duplicate();
			for (int l = 0; l < ActiveCompanions.Count; l++)
			{
				ActiveCompanions[l].GetComponentInChildren<CompanionInitializer>().EndOfBattleInitialize();
			}
		}
	}

	public void StoreAllCompanions()
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			if (ActiveCompanions[i] != null)
			{
				Object.Destroy(ActiveCompanions[i].GetComponent<SpriteControl>().SkeletonTransform.gameObject);
				Object.Destroy(ActiveCompanions[i].transform.parent.gameObject);
			}
		}
		ActiveCompanions.Clear();
		for (int j = 0; j < DecayedCompanions.Count; j++)
		{
			if (DecayedCompanions[j] != null)
			{
				Object.Destroy(DecayedCompanions[j].GetComponent<SpriteControl>().SkeletonTransform.gameObject);
				Object.Destroy(DecayedCompanions[j].transform.parent.gameObject);
			}
		}
		DecayedCompanions.Clear();
	}

	public bool IsAnyMustUseDice()
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			CompanionAbility component = ActiveCompanions[i].GetComponent<CompanionAbility>();
			if (!component.BasicDiceSpawned)
			{
				continue;
			}
			DiceInstance basicDiceInstance = component.BasicDiceInstance;
			if (CheckIfCompanionDiceContainsInteractions(basicDiceInstance) && basicDiceInstance.ActionEnabled)
			{
				"Companion has at least 1 must use action".DebugLogIfVerbose(verbose);
				return true;
			}
			if (component.IsBoosted && component.BoostDiceSpawned)
			{
				DiceInstance boostDiceInstance = component.BoostDiceInstance;
				if (CheckIfCompanionDiceContainsInteractions(boostDiceInstance) && boostDiceInstance.ActionEnabled)
				{
					"Companion has at least 1 must use action".DebugLogIfVerbose(verbose);
					return true;
				}
			}
		}
		"Companion has no must use action".DebugLogIfVerbose(verbose);
		return false;
	}

	public bool IsAnyPlayableNonMustUseActions()
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			CompanionAbility component = ActiveCompanions[i].GetComponent<CompanionAbility>();
			if (!component.BasicDiceSpawned)
			{
				continue;
			}
			DiceInstance basicDiceInstance = component.BasicDiceInstance;
			if (!CheckIfCompanionDiceContainsInteractions(basicDiceInstance) && basicDiceInstance.ActionEnabled && basicDiceInstance.ActionFace.BattleAction.CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.COMPANION))
			{
				"Companion has at least 1 Playable Non Must Use use action".DebugLogIfVerbose(verbose);
				return true;
			}
			if (component.IsBoosted && component.BoostDiceSpawned)
			{
				DiceInstance boostDiceInstance = component.BoostDiceInstance;
				if (!CheckIfCompanionDiceContainsInteractions(boostDiceInstance) && boostDiceInstance.ActionEnabled && boostDiceInstance.ActionFace.BattleAction.CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.COMPANION))
				{
					"Companion has at least 1 Playable Non Must Use use action".DebugLogIfVerbose(verbose);
					return true;
				}
			}
		}
		"Companion has no Playable Non Must Use action".DebugLogIfVerbose(verbose);
		return false;
	}

	private bool CheckIfCompanionDiceContainsInteractions(DiceInstance diceInstance)
	{
		return diceInstance.ActionFace.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum();
	}

	public bool PlayerHasCompanion(CompanionData companionData)
	{
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			if (runtimeCompanions[i].CompanionData == companionData)
			{
				return true;
			}
		}
		return false;
	}

	public int GetCompanionIndex(RuntimeCompanion runtimeCompanion)
	{
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			if (runtimeCompanions[i] == runtimeCompanion)
			{
				return i;
			}
		}
		return -1;
	}

	public int RemoveCompanion(RuntimeCompanion runtimeCompanion)
	{
		int result = -1;
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			if (runtimeCompanions[i] == runtimeCompanion)
			{
				result = i;
				runtimeCompanions.RemoveAt(i);
			}
		}
		return result;
	}

	public void UpdateCompanionCurrentCorruption()
	{
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			runtimeCompanions[i].SetCurrentCorruption((int)ActiveCompanions[i].GetComponent<CompanionCorruptionStats>().CurrentCorruption);
		}
	}

	public GameObject GetOtherCompanion(GameObject companion)
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			if (ActiveCompanions[i] != companion)
			{
				return ActiveCompanions[i];
			}
		}
		return null;
	}

	public int IsCompanionsWithAfflictionGetAmount()
	{
		int num = 0;
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			num += ActiveCompanions[i].GetComponent<UnitEffects>().IsAfflictionActiveGetAmount();
		}
		return num;
	}

	public int IsCompanionsWithEffectGetAmount(Effect effect)
	{
		int num = 0;
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			num += ActiveCompanions[i].GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false);
		}
		return num;
	}

	public void EnemyOvercorruptedActiveCompanionEffectWithSource(GameObject source)
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			ActiveCompanions[i].GetComponent<CompanionEffects>().EnemyOvercorruptedIsLockOnAndAutoTurretActiveActivateWithSource(source);
		}
	}

	public bool IsAllCompanionsOnMaxLevelAndHasTwoCompanions()
	{
		if (runtimeCompanions.Count < 2)
		{
			return false;
		}
		for (int i = 0; i < runtimeCompanions.Count; i++)
		{
			if (runtimeCompanions[i].CompanionLevel < 4)
			{
				return false;
			}
		}
		return true;
	}

	public GameObject IsOneCompanionAlreadyOnMaxLevelGetTheOtherCompanion()
	{
		List<GameObject> list = ActiveCompanions.Duplicate();
		for (int num = runtimeCompanions.Count - 1; num >= 0; num--)
		{
			if (runtimeCompanions[num].CompanionLevel == 4)
			{
				list.RemoveAt(num);
			}
		}
		if (list.Count == 1)
		{
			return list.First();
		}
		return null;
	}

	public void StoreCompanionsDice()
	{
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			ActiveCompanions[i].GetComponent<UnitsDiceActivation>().StoreDice();
		}
	}

	public void AddCompanion(RuntimeCompanion runtimeCompanion)
	{
		if (runtimeCompanions.Count < 2)
		{
			runtimeCompanions.Add(runtimeCompanion);
		}
		else
		{
			runtimeCompanions[runtimeCompanions.Count - 1] = runtimeCompanion;
		}
	}

	public void InsertCompanion(RuntimeCompanion runtimeCompanion, int positionIndex)
	{
		if (runtimeCompanions.Count < 2)
		{
			runtimeCompanions.Insert(positionIndex, runtimeCompanion);
		}
		else
		{
			runtimeCompanions[positionIndex] = runtimeCompanion;
		}
	}

	public List<DiceInstance> GetSentinelsDiceInstances()
	{
		List<DiceInstance> list = new List<DiceInstance>();
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			list.AddRange(ActiveCompanions[i].GetComponent<CompanionAbility>().GetDiceInstancesToRoll());
		}
		return list;
	}

	public int GetCompanionsWithAtLeastXAfflictionAmount(int afflictionToCompareAmount)
	{
		int num = 0;
		for (int i = 0; i < ActiveCompanions.Count; i++)
		{
			if (ActiveCompanions[i].GetComponent<UnitEffects>().IsAfflictionActiveGetAmount() >= afflictionToCompareAmount)
			{
				num++;
			}
		}
		return num;
	}
}
